-- Console schema for sqlite, generated by `scripts/dump_schema_sql.py` from `alembic upgrade head --sql`.
-- Do not edit: change `alembic/versions/` and re-run the script.
--
-- This file creates the tables *and* stamps `alembic_version`, so a database
-- initialised from it is already at head and `alembic upgrade head` is a no-op.
-- It is idempotent only in the sense that re-running it fails on the existing
-- tables — provision an empty database with it.
-- Needs SQLite 3.35+ (the version stamp is an INSERT ... RETURNING).

CREATE TABLE alembic_version (
    version_num VARCHAR(32) NOT NULL,
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 0001_initial

CREATE TABLE param_user (
    id INTEGER NOT NULL,
    username VARCHAR(64) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(16) DEFAULT 'operator' NOT NULL,
    disabled BOOLEAN DEFAULT 0 NOT NULL,
    created_at DATETIME NOT NULL,
    last_login_at DATETIME,
    PRIMARY KEY (id),
    UNIQUE (username)
);

CREATE TABLE param_draft (
    id INTEGER NOT NULL,
    profile VARCHAR(64) NOT NULL,
    base_version INTEGER DEFAULT '0' NOT NULL,
    patch JSON NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (profile)
);

CREATE TABLE param_version (
    id INTEGER NOT NULL,
    profile VARCHAR(64) NOT NULL,
    version INTEGER NOT NULL,
    status VARCHAR(16) NOT NULL,
    note VARCHAR(500) DEFAULT '' NOT NULL,
    author VARCHAR(64) DEFAULT '' NOT NULL,
    yaml_text TEXT DEFAULT '' NOT NULL,
    yaml_sha256 VARCHAR(64) DEFAULT '' NOT NULL,
    env_sha256 VARCHAR(64) DEFAULT '' NOT NULL,
    duration_s FLOAT,
    rolled_back_to INTEGER,
    error_code VARCHAR(48),
    created_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_version_profile_version UNIQUE (profile, version)
);

CREATE TABLE param_audit (
    id INTEGER NOT NULL,
    at DATETIME NOT NULL,
    actor VARCHAR(64) DEFAULT '' NOT NULL,
    role VARCHAR(16) DEFAULT '' NOT NULL,
    action VARCHAR(32) NOT NULL,
    profile VARCHAR(64) DEFAULT '' NOT NULL,
    version INTEGER,
    fields JSON NOT NULL,
    result VARCHAR(8) DEFAULT 'ok' NOT NULL,
    error_code VARCHAR(48),
    duration_s FLOAT,
    request_id VARCHAR(64) DEFAULT '' NOT NULL,
    PRIMARY KEY (id)
);

INSERT INTO alembic_version (version_num) VALUES ('0001_initial') RETURNING version_num;

-- Running upgrade 0001_initial -> 0003_voices

CREATE TABLE voices (
    id VARCHAR(26) NOT NULL,
    name VARCHAR(64) NOT NULL,
    source VARCHAR(16) NOT NULL,
    backend VARCHAR(16) NOT NULL,
    language VARCHAR(16),
    status VARCHAR(16) DEFAULT 'draft' NOT NULL,
    audio_relpath VARCHAR(255),
    audio_bytes INTEGER DEFAULT '0' NOT NULL,
    audio_seconds FLOAT DEFAULT '0' NOT NULL,
    trim_start_ms INTEGER DEFAULT '0' NOT NULL,
    trim_end_ms INTEGER,
    ref_text TEXT,
    instruct TEXT,
    spk_relpath VARCHAR(255),
    rvq_relpath VARCHAR(255),
    error_code VARCHAR(32),
    created_at DATETIME NOT NULL,
    created_by VARCHAR(64) NOT NULL,
    consent_ack_at DATETIME NOT NULL,
    retention_days INTEGER DEFAULT '30' NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_voices_name UNIQUE (name)
);

CREATE INDEX ix_voices_status ON voices (status);

UPDATE alembic_version SET version_num='0003_voices' WHERE alembic_version.version_num = '0001_initial';

-- Running upgrade 0003_voices -> 0004_turn_latency

CREATE TABLE turn_latency (
    response_key VARCHAR(96) NOT NULL,
    turn_revision INTEGER NOT NULL,
    turn_id VARCHAR(96),
    source VARCHAR(16) DEFAULT '' NOT NULL,
    status VARCHAR(16) DEFAULT '' NOT NULL,
    smart_status VARCHAR(16),
    e2e_ms INTEGER,
    stt_ms INTEGER,
    llm_ms INTEGER,
    tts_ttfa_ms INTEGER,
    vad_decision_ms INTEGER,
    hold_ms INTEGER,
    logged_at DATETIME NOT NULL,
    raw_offset INTEGER DEFAULT '0' NOT NULL,
    ingested_at DATETIME NOT NULL,
    PRIMARY KEY (response_key, turn_revision)
);

CREATE INDEX ix_turn_latency_logged_at ON turn_latency (logged_at);

UPDATE alembic_version SET version_num='0004_turn_latency' WHERE alembic_version.version_num = '0003_voices';

-- Running upgrade 0004_turn_latency -> 0005_instances

CREATE TABLE param_instance (
    id INTEGER NOT NULL,
    instance_id VARCHAR(64) NOT NULL,
    base_url VARCHAR(255) NOT NULL,
    weight INTEGER DEFAULT '1' NOT NULL,
    max_sessions_hint INTEGER,
    labels_json JSON NOT NULL,
    enabled BOOLEAN DEFAULT '1' NOT NULL,
    drain_requested BOOLEAN DEFAULT '0' NOT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_instance_instance_id UNIQUE (instance_id)
);

CREATE TABLE param_instance_metric (
    id INTEGER NOT NULL,
    instance_id VARCHAR(64) NOT NULL,
    observed_at DATETIME NOT NULL,
    observed_by VARCHAR(64) NOT NULL,
    kind VARCHAR(16) DEFAULT 'sample' NOT NULL,
    size INTEGER,
    in_use INTEGER,
    free INTEGER,
    stuck INTEGER,
    status VARCHAR(16) NOT NULL,
    probe_ms INTEGER,
    alloc_ok INTEGER DEFAULT '0' NOT NULL,
    alloc_fail_no_instance INTEGER DEFAULT '0' NOT NULL,
    alloc_fail_instance_503 INTEGER DEFAULT '0' NOT NULL,
    evict_count INTEGER DEFAULT '0' NOT NULL,
    recover_count INTEGER DEFAULT '0' NOT NULL,
    PRIMARY KEY (id)
);

CREATE INDEX ix_param_instance_metric_instance_id ON param_instance_metric (instance_id);

CREATE INDEX ix_param_instance_metric_observed_at ON param_instance_metric (observed_at);

UPDATE alembic_version SET version_num='0005_instances' WHERE alembic_version.version_num = '0004_turn_latency';

